/**
 * 写入待选房屋列表。楼幢接口 /presale/houseInfo/queryHousesByBuildCode 会
 * 忽略 pageNum 一次返回全量户室，需按当前页码切片；后端已分页时原样使用。
 * 翻页同步清空待选勾选，避免把上一页的勾选带到下一页（#6235）。
 */
applyOriginPage (res) {
  const { rows, total } = unwrapPageResult(res)
  const page = paginateRows(rows, total, this.queryParams.pageNum, this.queryParams.pageSize)
  this.originData = page.rows
  this.total = page.total
  this.selectedOrigin = []
  this.syncOriginSelection()
},
async getListByBuilding () {
  const { isCurrent } = beginDialogAsyncLoad(this, 'originListLoadSeq')
  const res = await queryHousesByBuildCode({ ...this.queryParams, contractType: this.contractType })
  if (!isCurrent()) return
  this.applyOriginPage(res)
},
async getListByUnit () {
  const { isCurrent } = beginDialogAsyncLoad(this, 'originListLoadSeq')
  const res = await getHouseList({ ...this.queryParams, contractType: this.contractType })
  if (!isCurrent()) return
  this.applyOriginPage(res)
},

